.numbered-posts{gap:10px}
.numbered-post{flex-direction:row;gap:15px}
.category-section .category-grid{flex-direction:column}
.category-section .category-main,.category-section .category-sidebar{width:100%}
.team-grid{grid-template-columns:repeat(2,1fr);gap:15px}
.features-grid{grid-template-columns:1fr;gap:20px}
.gallery-grid{grid-template-columns:repeat(3,1fr)}
.gallery-masonry{column-count:2}
}

/* Mobile Portrait */
@media screen and (max-width:575px){
html{font-size:14px}
.topbar{padding:6px 0;font-size:11px}
