}

/* Dark Mode Sidebar Fix */
.dark-mode .sidebar-widget { background: #1e1e2d !important; border: 1px solid #333; }
.dark-mode .widget-title { background: #2d2d44 !important; color: #fff !important; }
.dark-mode .sidebar-widget a { color: #e0e0e0; }
.dark-mode .sidebar-widget a:hover { color: #fff; }

body.script:
//
(function(){
'use strict';

// DOM Ready
document.addEventListener('DOMContentLoaded', function() {

// ========== CURRENT DATE ==========
var dateEl = document.getElementById('current-date');
if(dateEl) {
  var options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
  dateEl.textContent = new Date().toLocaleDateString('en-US', options);
}

// ========== COPYRIGHT YEAR ==========
var yearEl = document.getElementById('copyright-year');
if(yearEl) {
  yearEl.textContent = new Date().getFullYear();
}

// ========== MOBILE MENU TOGGLE ==========
var menuToggle = document.getElementById('menu-toggle');
var mainMenu = document.getElementById('main-menu');
if(menuToggle && mainMenu) {
  menuToggle.addEventListener('click', function() {
    mainMenu.classList.toggle('active');
    this.setAttribute('aria-expanded', mainMenu.classList.contains('active'));
  });
}

// ========== STICKY NAVIGATION ==========
var nav = document.getElementById('navigation');
var navOffset = nav ? nav.offsetTop : 0;
function handleStickyNav() {
  if(window.pageYOffset > navOffset + 100) {
    nav.classList.add('is-sticky');
  } else {
    nav.classList.remove('is-sticky');
  }
}

// ========== READING PROGRESS BAR ==========
var progressBar = document.getElementById('reading-progress');
function updateReadingProgress() {
  if(!progressBar) return;
  var docHeight = document.documentElement.scrollHeight - window.innerHeight;
  var scrollPos = window.scrollY;
  var progress = (scrollPos / docHeight) * 100;
  progressBar.style.width = progress + '%';
}

// ========== BACK TO TOP BUTTON ==========
var backToTop = document.getElementById('back-to-top');
function handleBackToTop() {
  if(!backToTop) return;
  if(window.pageYOffset > 400) {
    backToTop.classList.add('visible');
  } else {
    backToTop.classList.remove('visible');
  }
}
if(backToTop) {
  backToTop.addEventListener('click', function() {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
}

// ========== SCROLL EVENT HANDLER ==========
var ticking = false;
window.addEventListener('scroll', function() {
  if(!ticking) {
    window.requestAnimationFrame(function() {
      handleStickyNav();
      updateReadingProgress();
      handleBackToTop();
      ticking = false;
    });
    ticking = true;
  }
}, { passive: true });

// ========== DARK MODE TOGGLE ==========
var darkToggle = document.getElementById('dark-toggle');
var htmlElement = document.documentElement;
var savedTheme = localStorage.getItem('theme');

function setTheme(theme) {
  if(theme === 'dark') {
    htmlElement.classList.add('dark-mode');
    localStorage.setItem('theme', 'dark');
    if(darkToggle) {
      darkToggle.querySelector('.sun-icon').style.display = 'none';
      darkToggle.querySelector('.moon-icon').style.display = 'block';
    }
  } else {
    htmlElement.classList.remove('dark-mode');
    localStorage.setItem('theme', 'light');
    if(darkToggle) {
      darkToggle.querySelector('.sun-icon').style.display = 'block';
      darkToggle.querySelector('.moon-icon').style.display = 'none';
    }
  }
}

// Initialize theme
if(savedTheme) {
  setTheme(savedTheme);
} else if(window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
  setTheme('dark');
}

if(darkToggle) {
  darkToggle.addEventListener('click', function() {
    var currentTheme = htmlElement.classList.contains('dark-mode') ? 'light' : 'dark';
    setTheme(currentTheme);
  });
}

// ========== COOKIE NOTICE ==========
var cookieNotice = document.getElementById('cookie-notice');
var acceptCookies = document.getElementById('accept-cookies');
var declineCookies = document.getElementById('decline-cookies');

if(cookieNotice && !localStorage.getItem('cookiesAccepted')) {
  setTimeout(function() {
    cookieNotice.classList.add('show');
  }, 2000);
}

if(acceptCookies) {
  acceptCookies.addEventListener('click', function() {
    localStorage.setItem('cookiesAccepted', 'true');
    cookieNotice.classList.remove('show');
  });
}

if(declineCookies) {
  declineCookies.addEventListener('click', function() {
    localStorage.setItem('cookiesAccepted', 'false');
    cookieNotice.classList.remove('show');
  });
}

// ========== COPY LINK BUTTON ==========
var copyButtons = document.querySelectorAll('.share-btn.copy');
copyButtons.forEach(function(btn) {
  btn.addEventListener('click', function() {
    var url = window.location.href;
    navigator.clipboard.writeText(url).then(function() {
      btn.querySelector('span').textContent = 'Copied!';
      setTimeout(function() {
        btn.querySelector('span').textContent = 'Copy';
      }, 2000);
    });
  });
});

// ========== LAZY LOADING IMAGES ==========
if('loading' in HTMLImageElement.prototype) {
  var lazyImages = document.querySelectorAll('img[loading="lazy"]');
  lazyImages.forEach(function(img) {
    if(!img.src && img.dataset.src) {
      img.src = img.dataset.src;
    }
  });
} else {
  // Fallback for browsers that don't support native lazy loading
  var lazyImages = document.querySelectorAll('img[loading="lazy"]');
  var imageObserver = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if(entry.isIntersecting) {
        var img = entry.target;
        if(img.dataset.src) {
          img.src = img.dataset.src;
        }
        imageObserver.unobserve(img);
      }
    });
  }, { rootMargin: '50px 0px' });

  lazyImages.forEach(function(img) {
    imageObserver.observe(img);
  });
}

// ========== SEARCH OVERLAY ==========
var navSearchBtn = document.getElementById('nav-search-btn');
var headerSearch = document.querySelector('.header-search input');
if(navSearchBtn && headerSearch) {
  navSearchBtn.addEventListener('click', function() {
    headerSearch.focus();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
}

// ========== DROPDOWN MENU ACCESSIBILITY ==========
var menuItems = document.querySelectorAll('.main-menu > li');
menuItems.forEach(function(item) {
  var link = item.querySelector('a');
  var submenu = item.querySelector('.dropdown-menu, .mega-menu');
  if(submenu) {
    link.setAttribute('aria-haspopup', 'true');
    link.setAttribute('aria-expanded', 'false');
    
    item.addEventListener('mouseenter', function() {
      link.setAttribute('aria-expanded', 'true');
    });
    
    item.addEventListener('mouseleave', function() {
      link.setAttribute('aria-expanded', 'false');
    });
  }
});

// ========== SMOOTH SCROLL FOR ANCHOR LINKS ==========
document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
  anchor.addEventListener('click', function(e) {
    var target = document.querySelector(this.getAttribute('href'));
    if(target) {
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  });
});

// ========== EXTERNAL LINKS HANDLER ==========
document.querySelectorAll('a[href^="http"]').forEach(function(link) {
  if(!link.href.includes(window.location.hostname)) {
    link.setAttribute('target', '_blank');
    link.setAttribute('rel', 'noopener noreferrer');
  }
});

// ========== PRINT BUTTON HANDLER ==========
var printButtons = document.querySelectorAll('.print-btn');
printButtons.forEach(function(btn) {
  btn.addEventListener('click', function() {
    window.print();
  });
});

}); // End DOMContentLoaded

// ========== PERFORMANCE: Preload critical resources ==========
window.addEventListener('load', function() {
  // Preload fonts
  var link = document.createElement('link');
  link.rel = 'preload';
  link.as = 'font';
  link.type = 'font/woff2';
  link.href = 'https://fonts.gstatic.com/s/inter/v12/UcCO3FwrK3iLTeHuS_fvQtMwCp50KnMw2boKoduKmMEVuLyfAZ9hjp-Ek-_EeA.woff2';
  link.crossOrigin = 'anonymous';
  document.head.appendChild(link);
});

})();
//

//
(function(){
'use strict';

// ========== TABLE OF CONTENTS GENERATOR ==========
function generateTOC() {
  var postBody = document.querySelector('.post-body');
  if(!postBody) return;
  
  var headings = postBody.querySelectorAll('h2, h3, h4');
  if(headings.length < 3) return;
  
  var toc = document.createElement('nav');
  toc.className = 'toc-container';
  toc.innerHTML = '<h4><svg viewBox="0 0 24 24" width="18" height="18"><path fill="currentColor" d="M3 9h14V7H3v2zm0 4h14v-2H3v2zm0 4h14v-2H3v2zm16 0h2v-2h-2v2zm0-10v2h2V7h-2zm0 6h2v-2h-2v2z"/></svg> Table of Contents</h4><ul></ul>';
  
  var list = toc.querySelector('ul');
  headings.forEach(function(heading, index) {
    var id = 'heading-' + index;
    heading.id = id;
    
    var li = document.createElement('li');
    li.className = heading.tagName.toLowerCase();
    li.innerHTML = '<a href="#' + id + '">' + heading.textContent + '</a>';
    list.appendChild(li);
  });
  
  var firstHeading = postBody.querySelector('h2, h3, p');
  if(firstHeading) {
    postBody.insertBefore(toc, firstHeading.nextSibling);
  }
}

// ========== READING TIME CALCULATOR ==========
function calculateReadingTime() {
  var postBody = document.querySelector('.post-body');
  if(!postBody) return;
  
  var text = postBody.textContent || postBody.innerText;
  var wordCount = text.split(/\s+/).length;
  var readingTime = Math.ceil(wordCount / 200);
  
  var readingTimeElements = document.querySelectorAll('.reading-time');
  readingTimeElements.forEach(function(el) {
    el.innerHTML = '<svg viewBox="0 0 24 24" width="14" height="14"><path fill="currentColor" d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67z"/></svg> ' + readingTime + ' min read';
  });
}

// ========== LIGHTBOX FOR IMAGES ==========
function initLightbox() {
  var images = document.querySelectorAll('.post-body img');
  if(!images.length) return;
  
  var lightbox = document.createElement('div');
  lightbox.className = 'lightbox';
  lightbox.innerHTML = '<button class="close" aria-label="Close"><svg viewBox="0 0 24 24"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg></button><img src="" alt=""/><div class="caption"></div>';
  document.body.appendChild(lightbox);
  
  var lightboxImg = lightbox.querySelector('img');
  var lightboxCaption = lightbox.querySelector('.caption');
  var closeBtn = lightbox.querySelector('.close');
  
  images.forEach(function(img) {
    img.style.cursor = 'zoom-in';
    img.addEventListener('click', function() {
      lightboxImg.src = this.src;
      lightboxImg.alt = this.alt;
      lightboxCaption.textContent = this.alt || '';
      lightbox.classList.add('active');
      document.body.style.overflow = 'hidden';
    });
  });
  
  closeBtn.addEventListener('click', closeLightbox);
  lightbox.addEventListener('click', function(e) {
    if(e.target === lightbox) closeLightbox();
  });
  
  document.addEventListener('keydown', function(e) {
    if(e.key === 'Escape' && lightbox.classList.contains('active')) {
      closeLightbox();
    }
  });
  
  function closeLightbox() {
    lightbox.classList.remove('active');
    document.body.style.overflow = '';
  }
}

// ========== SCROLL SPY FOR TOC ==========
function initScrollSpy() {
  var headings = document.querySelectorAll('.post-body h2[id], .post-body h3[id], .post-body h4[id]');
  var tocLinks = document.querySelectorAll('.toc-container a');
  
  if(!headings.length || !tocLinks.length) return;
  
  var observer = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if(entry.isIntersecting) {
        tocLinks.forEach(function(link) {
          link.classList.remove('active');
          if(link.getAttribute('href') === '#' + entry.target.id) {
            link.classList.add('active');
          }
        });
      }
    });
  }, { rootMargin: '-20% 0px -80% 0px' });
  
  headings.forEach(function(heading) {
    observer.observe(heading);
  });
}

// ========== AJAX LOAD MORE ==========
function initLoadMore() {
  var loadMoreBtn = document.querySelector('.load-more button');
  var postsContainer = document.querySelector('.posts-list');
  
  if(!loadMoreBtn || !postsContainer) return;
  
  loadMoreBtn.addEventListener('click', function() {
    var btn = this;
    var nextUrl = btn.dataset.next;
    
    if(!nextUrl) return;
    
    btn.classList.add('loading');
    btn.textContent = 'Loading...';
    
    fetch(nextUrl)
      .then(function(response) { return response.text(); })
      .then(function(html) {
        var parser = new DOMParser();
        var doc = parser.parseFromString(html, 'text/html');
        var newPosts = doc.querySelectorAll('.posts-list .post-card');
        var newNextLink = doc.querySelector('.pagination .next');
        
        newPosts.forEach(function(post) {
          post.classList.add('fade-in');
          postsContainer.appendChild(post);
        });
        
        if(newNextLink) {
          btn.dataset.next = newNextLink.href;
          btn.textContent = 'Load More';
        } else {
          btn.style.display = 'none';
        }
        
        btn.classList.remove('loading');
      })
      .catch(function() {
        btn.textContent = 'Error. Try again.';
        btn.classList.remove('loading');
      });
  });
}

// ========== SEARCH AUTOCOMPLETE ==========
function initSearchAutocomplete() {
  var searchInputs = document.querySelectorAll('.header-search input');
  
  searchInputs.forEach(function(input) {
    var wrapper = input.parentElement;
    var suggestionsDiv = document.createElement('div');
    suggestionsDiv.className = 'search-suggestions';
    wrapper.appendChild(suggestionsDiv);
    
    var debounceTimer;
    input.addEventListener('input', function() {
      clearTimeout(debounceTimer);
      var query = this.value.trim();
      
      if(query.length < 2) {
        suggestionsDiv.innerHTML = '';
        suggestionsDiv.style.display = 'none';
        return;
      }
      
      debounceTimer = setTimeout(function() {
        // Placeholder for search API
        suggestionsDiv.innerHTML = '<div class="suggestion-item">Search for: ' + query + '</div>';
        suggestionsDiv.style.display = 'block';
      }, 300);
    });
    
    document.addEventListener('click', function(e) {
      if(!wrapper.contains(e.target)) {
        suggestionsDiv.style.display = 'none';
      }
    });
  });
}

// ========== TABS FUNCTIONALITY ==========
function initTabs() {
  var tabContainers = document.querySelectorAll('.tabbed-widget');
  
  tabContainers.forEach(function(container) {
    var tabs = container.querySelectorAll('.tabs button');
    var panes = container.querySelectorAll('.tab-content');
    
    tabs.forEach(function(tab, index) {
      tab.addEventListener('click', function() {
        tabs.forEach(function(t) { t.classList.remove('active'); });
        panes.forEach(function(p) { p.classList.remove('active'); });
        
        tab.classList.add('active');
        if(panes[index]) panes[index].classList.add('active');
      });
    });
  });
}

// ========== ACCORDION FUNCTIONALITY ==========
function initAccordions() {
  var accordions = document.querySelectorAll('.accordion-item');
  
  accordions.forEach(function(item) {
    var header = item.querySelector('.accordion-header');
    if(!header) return;
    
    header.addEventListener('click', function() {
      var isActive = item.classList.contains('active');
      
      // Close all
      document.querySelectorAll('.accordion-item').forEach(function(i) {
        i.classList.remove('active');
      });
      
      // Open clicked if not already active
      if(!isActive) {
        item.classList.add('active');
      }
    });
  });
}

// ========== FORM VALIDATION ==========
function initFormValidation() {
  var forms = document.querySelectorAll('form[data-validate]');
  
  forms.forEach(function(form) {
    form.addEventListener('submit', function(e) {
      var isValid = true;
      var inputs = form.querySelectorAll('[required]');
      
      inputs.forEach(function(input) {
        var value = input.value.trim();
        var errorDiv = input.parentElement.querySelector('.form-error');
        
        if(!value) {
          isValid = false;
          input.classList.add('error');
          if(errorDiv) errorDiv.textContent = 'This field is required';
        } else if(input.type === 'email' && !validateEmail(value)) {
          isValid = false;
          input.classList.add('error');
          if(errorDiv) errorDiv.textContent = 'Please enter a valid email';
        } else {
          input.classList.remove('error');
          if(errorDiv) errorDiv.textContent = '';
        }
      });
      
      if(!isValid) e.preventDefault();
    });
  });
  
  function validateEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }
}

// ========== COUNTDOWN TIMER ==========
function initCountdown() {
  var countdowns = document.querySelectorAll('[data-countdown]');
  
  countdowns.forEach(function(el) {
    var targetDate = new Date(el.dataset.countdown).getTime();
    
    var timer = setInterval(function() {
      var now = new Date().getTime();
      var distance = targetDate - now;
      
      if(distance < 0) {
        clearInterval(timer);
        el.innerHTML = '<span class="expired">Expired</span>';
        return;
      }
      
      var days = Math.floor(distance / (1000 * 60 * 60 * 24));
      var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
      var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
      var seconds = Math.floor((distance % (1000 * 60)) / 1000);
      
      el.innerHTML = 
        '<div class="countdown-item"><span class="number">' + days + '</span><span class="label">Days</span></div>' +
        '<div class="countdown-item"><span class="number">' + hours + '</span><span class="label">Hours</span></div>' +
        '<div class="countdown-item"><span class="number">' + minutes + '</span><span class="label">Minutes</span></div>' +
        '<div class="countdown-item"><span class="number">' + seconds + '</span><span class="label">Seconds</span></div>';
    }, 1000);
  });
}

// ========== NOTIFICATION SYSTEM ==========
window.showNotification = function(message, type, duration) {
  type = type || 'info';
  duration = duration || 5000;
  
  var notification = document.createElement('div');
  notification.className = 'notification ' + type;
  notification.innerHTML = message + '<span class="close">&times;</span>';
  
  document.body.appendChild(notification);
  
  setTimeout(function() {
    notification.classList.add('show');
  }, 100);
  
  var closeBtn = notification.querySelector('.close');
  closeBtn.addEventListener('click', function() {
    notification.classList.remove('show');
    setTimeout(function() {
      notification.remove();
    }, 300);
  });
  
  setTimeout(function() {
    notification.classList.remove('show');
    setTimeout(function() {
      notification.remove();
    }, 300);
  }, duration);
};

// ========== INTERSECTION OBSERVER FOR ANIMATIONS ==========
function initScrollAnimations() {
  var animatedElements = document.querySelectorAll('[data-animate]');
  
  if(!animatedElements.length) return;
  
  var observer = new IntersectionObserver(function(entries) {
    entries.forEach(function(entry) {
      if(entry.isIntersecting) {
        entry.target.classList.add('animated');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1 });
  
  animatedElements.forEach(function(el) {
    observer.observe(el);
  });
}

// ========== SOCIAL SHARE POPUP ==========
function initShareButtons() {
  var shareButtons = document.querySelectorAll('.share-btn[target="_blank"]');
  
  shareButtons.forEach(function(btn) {
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      var url = this.href;
      var width = 600;
      var height = 400;
      var left = (window.innerWidth - width) / 2;
      var top = (window.innerHeight - height) / 2;
      
      window.open(url, 'share', 'width=' + width + ',height=' + height + ',left=' + left + ',top=' + top);
    });
  });
}

// ========== PRINT FUNCTIONALITY ==========
function initPrintButton() {
  var printBtns = document.querySelectorAll('[data-print]');
  
  printBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      window.print();
    });
  });
}

// ========== FONT SIZE ADJUSTER ==========
window.adjustFontSize = function(action) {
  var postBody = document.querySelector('.post-body');
  if(!postBody) return;
  
  var currentSize = parseFloat(window.getComputedStyle(postBody).fontSize);
  var newSize;
  
  if(action === 'increase' && currentSize < 24) {
    newSize = currentSize + 2;
  } else if(action === 'decrease' && currentSize > 12) {
    newSize = currentSize - 2;
  } else if(action === 'reset') {
    newSize = 17;
  } else {
    return;
  }
  
  postBody.style.fontSize = newSize + 'px';
  localStorage.setItem('fontSize', newSize);
};

// Apply saved font size
function applySavedFontSize() {
  var savedSize = localStorage.getItem('fontSize');
  if(savedSize) {
    var postBody = document.querySelector('.post-body');
    if(postBody) {
      postBody.style.fontSize = savedSize + 'px';
    }
  }
}

// ========== INITIALIZE ALL ==========
document.addEventListener('DOMContentLoaded', function() {
  generateTOC();
  calculateReadingTime();
  initLightbox();
  initScrollSpy();
  initTabs();
  initAccordions();
  initFormValidation();
  initCountdown();
  initScrollAnimations();
  initShareButtons();
  initPrintButton();
  applySavedFontSize();
});

})();
